{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Dapoxetine, a lipophilic tertiary-amine drug with high transferability, has an absolute oral bioavailability of 42% in healthy volunteers, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ciramadol, a basic amine with phenolic and hydroxyl groups and high transferability, shows 80 ± 7% oral bioavailability, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Actisomide, a phenyl-containing basic amide with high transferability, has an absolute oral bioavailability of 30–43% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Fentanyl, a tertiary amide with a basic piperidine and aromatic groups, has an absolute oral bioavailability of 35% in healthy volunteers, supporting high bioavailability for this amide/amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Doxapram, a diphenyl amide/lactam with basic amine and moderate transferability, shows ~60% systemic availability after oral dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Loperamide, a structurally related tertiary amide/basic amine, has very low absolute oral bioavailability (0.3%) attributed to P-gp efflux and poor solubility; however, its transferability is low and the query lacks key loperamide features such as the para-chlorophenyl and piperidine arrangement.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable experimental evidence from structurally related lipophilic basic amides/amines consistently shows absolute oral bioavailability ≥20% (dapoxetine 42%, ciramadol 80%, actisomide 30–43%, fentanyl 30–50%, doxapram ~60%). The closest low-F analogue, loperamide, has low transferability and its poor bioavailability is driven by P-gp/solubility liabilities not clearly shared by the query. Overall, the balance of evidence supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental data for the query molecule itself.",
    "Uncertainty about whether the query is a P-gp substrate or has significant first-pass metabolism.",
    "No direct solubility or dissolution data for the query, though logD and TPSA are favorable.",
    "Loperamide's low bioavailability is structurally relevant but its low transferability limits its weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

